// --- Arrow C data interface -----------------------------------------------------------------

/// `struct ArrowSchema` of the Arrow C data interface.
#[repr(C)]
#[derive(Debug)]
pub struct ArrowSchema {
    pub format: *const c_char,
    pub name: *const c_char,
    pub metadata: *const c_char,
    pub flags: i64,
    pub n_children: i64,
    pub children: *mut *mut ArrowSchema,
    pub dictionary: *mut ArrowSchema,
    pub release: Option<unsafe extern "C" fn(*mut ArrowSchema)>,
    pub private_data: *mut c_void,
}

/// `struct ArrowArray` of the Arrow C data interface.
#[repr(C)]
#[derive(Debug)]
pub struct ArrowArray {
    pub length: i64,
    pub null_count: i64,
    pub offset: i64,
    pub n_buffers: i64,
    pub n_children: i64,
    pub buffers: *mut *const c_void,
    pub children: *mut *mut ArrowArray,
    pub dictionary: *mut ArrowArray,
    pub release: Option<unsafe extern "C" fn(*mut ArrowArray)>,
    pub private_data: *mut c_void,
}

/// `struct ArrowArrayStream` of the Arrow C stream interface.
#[repr(C)]
#[derive(Debug)]
pub struct ArrowArrayStream {
    pub get_schema: Option<unsafe extern "C" fn(*mut ArrowArrayStream, *mut ArrowSchema) -> c_int>,
    pub get_next: Option<unsafe extern "C" fn(*mut ArrowArrayStream, *mut ArrowArray) -> c_int>,
    pub get_last_error: Option<unsafe extern "C" fn(*mut ArrowArrayStream) -> *const c_char>,
    pub release: Option<unsafe extern "C" fn(*mut ArrowArrayStream)>,
    pub private_data: *mut c_void,
}

impl ArrowSchema {
    /// A released (null `release`) placeholder for a producer to fill.
    pub const fn empty() -> Self {
        Self {
            format: std::ptr::null(),
            name: std::ptr::null(),
            metadata: std::ptr::null(),
            flags: 0,
            n_children: 0,
            children: std::ptr::null_mut(),
            dictionary: std::ptr::null_mut(),
            release: None,
            private_data: std::ptr::null_mut(),
        }
    }
}

impl ArrowArray {
    /// A released (null `release`) placeholder for a producer to fill.
    pub const fn empty() -> Self {
        Self {
            length: 0,
            null_count: 0,
            offset: 0,
            n_buffers: 0,
            n_children: 0,
            buffers: std::ptr::null_mut(),
            children: std::ptr::null_mut(),
            dictionary: std::ptr::null_mut(),
            release: None,
            private_data: std::ptr::null_mut(),
        }
    }
}

impl ArrowArrayStream {
    /// A released (null `release`) placeholder for a producer to fill.
    pub const fn empty() -> Self {
        Self {
            get_schema: None,
            get_next: None,
            get_last_error: None,
            release: None,
            private_data: std::ptr::null_mut(),
        }
    }
}

// --- value structs ----------------------------------------------------------------------------

/// A borrowed, length-delimited string view (`duckdb_v2_str`). `{NULL, 0}` is the empty view.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct duckdb_v2_str {
    pub ptr: *const c_char,
    pub len: idx_t,
}

impl duckdb_v2_str {
    /// The canonical empty view.
    pub const EMPTY: duckdb_v2_str = duckdb_v2_str { ptr: std::ptr::null(), len: 0 };
}

impl Default for duckdb_v2_str {
    /// [`duckdb_v2_str::EMPTY`].
    fn default() -> Self {
        Self::EMPTY
    }
}

// Rust-to-C views of borrowed text for `in` parameters (the orphan rule keeps them in this crate; reading through a
// view the engine returned stays `unsafe` on the caller's side).
impl From<&str> for duckdb_v2_str {
    fn from(text: &str) -> Self {
        duckdb_v2_str { ptr: text.as_ptr() as *const c_char, len: text.len() as idx_t }
    }
}

impl From<&String> for duckdb_v2_str {
    fn from(text: &String) -> Self {
        text.as_str().into()
    }
}

/// The pointer form of [`duckdb_v2_bytes`]: used when the length exceeds
/// [`DUCKDB_V2_BYTES_INLINE_LENGTH`].
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct duckdb_v2_bytes_pointer {
    pub length: u32,
    pub prefix: [c_char; 4],
    pub ptr: *mut c_char,
}

/// The inlined form of [`duckdb_v2_bytes`]: the bytes live inside the struct.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct duckdb_v2_bytes_inlined {
    pub length: u32,
    pub inlined: [c_char; 12],
}

/// The transparent union inside [`duckdb_v2_bytes`].
#[repr(C)]
#[derive(Clone, Copy)]
pub union duckdb_v2_bytes_value {
    pub pointer: duckdb_v2_bytes_pointer,
    pub inlined: duckdb_v2_bytes_inlined,
}

/// 16-byte storage for a variable-size value: VARCHAR, BLOB, BIT, or BIGNUM. Layout-identical to
/// the engine's `string_t`.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct duckdb_v2_bytes {
    pub value: duckdb_v2_bytes_value,
}

impl duckdb_v2_bytes {
    /// The length of the stored bytes (shared by both union members).
    pub fn length(&self) -> u32 {
        // SAFETY(layout L5.I6): both union members start with the same `u32 length` field.
        unsafe { self.value.inlined.length }
    }
}

/// An opaque, owned handle to a caller-defined resource with optional destroy/equals callbacks.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct duckdb_v2_opaque {
    pub ptr: *mut c_void,
    pub destroy: duckdb_v2_opaque_destroy_fn,
    pub equals: duckdb_v2_opaque_equals_fn,
}

/// What an extension entrypoint receives (`struct duckdb_v2_extension_input`).
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct duckdb_v2_extension_input {
    pub get_api: duckdb_v2_extension_get_api_fn,
    pub extension: duckdb_v2_extension_handle,
    pub context: duckdb_v2_context_handle,
    pub err: *mut duckdb_v2_error_info_handle,
}

/// A read-only view of a vector's data, validity and selection (`duckdb_v2_vector_view`). `data_count` is not a
/// member of the engine's struct (data, validity, sel, count): the engine never writes it and the wrapper derives it
/// (`Vector::view` of `duckdb-ext-api`) as the number of entries `data` addresses, the bound of every physical index.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct duckdb_v2_vector_view {
    pub data: *const c_void,
    pub validity: *const u64,
    pub sel: *const duckdb_v2_sel_t,
    pub count: idx_t,
    pub data_count: idx_t,
}

/// A LIST entry: offset and length into the child vector (`list_entry_t`).
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct duckdb_v2_list_entry {
    pub offset: idx_t,
    pub length: idx_t,
}

/// A 128-bit signed integer (`hugeint_t`): `lower` + `upper << 64`.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct duckdb_v2_hugeint_t {
    pub lower: u64,
    pub upper: i64,
}

/// A 128-bit unsigned integer (`uhugeint_t`).
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct duckdb_v2_uhugeint_t {
    pub lower: u64,
    pub upper: u64,
}

/// An INTERVAL (`interval_t`): months, days and microseconds.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct duckdb_v2_interval_t {
    pub months: i32,
    pub days: i32,
    pub micros: i64,
}

// --- statically linked extensions (duckdb_static_extension.h) ---------------------------------

/// `DUCKDB_EXTENSION_DESCRIPTOR_VERSION`: the descriptor layout `duckdb_static_extension.h` defines.
pub const DUCKDB_EXTENSION_DESCRIPTOR_VERSION: u32 = 2;

/// `struct duckdb_extension_descriptor`: describes a statically linked extension (or something linked the same
/// way that is not an extension). The engine allocates and zero-fills it, the describe function fills it in.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct duckdb_extension_descriptor {
    /// In: the layout the engine offers. Out: the layout the describe function filled, never higher than the offer.
    pub version: u32,
    /// Layout 1, set by the engine: reports why the describe function refused (the engine copies the message).
    pub set_error: Option<unsafe extern "C" fn(*mut duckdb_extension_descriptor, *const c_char)>,
    /// Layout 1, set by the engine: its state for `set_error`, opaque to the extension.
    pub internal: *mut c_void,
    /// Layout 1, set by the extension; the engine copies the strings before the describe function's caller returns.
    pub name: *const c_char,
    pub extension_version: *const c_char,
    /// What the entry point was built against (the DuckDB version for `entry_cpp`, the C API version for the C
    /// entry points): recorded and reported, a mismatch is not refused yet.
    pub api_version: *const c_char,
    /// `void (duckdb::ExtensionLoader &)`.
    pub entry_cpp: Option<unsafe extern "C" fn()>,
    /// `bool (duckdb_extension_info, struct duckdb_extension_access *)`.
    pub entry_capi_v1: Option<unsafe extern "C" fn()>,
    /// `void (struct duckdb_v2_extension_input *)`.
    pub entry_capi_v2: Option<unsafe extern "C" fn()>,
    /// Layout 2, set by the describe function instead of an entry point: `void (duckdb::DatabaseInstance &)`, called
    /// for every database opened, before the extensions load.
    pub database_callback: Option<unsafe extern "C" fn()>,
}

/// `duckdb_extension_describe_t`: `duckdb_extension_<name>_describe`, returns 0 on success.
pub type duckdb_extension_describe_t = Option<unsafe extern "C" fn(*mut duckdb_extension_descriptor) -> i32>;

